from app.agents.contracts import AnalysisRequest, AnalysisResponse, EvidenceItem, InvestigatorHandoff, PredictionHandoff, InsightHandoff, AgentExecutionTrace, MatchContextArgs, HeadToHeadArgs, TeamFormArgs, PlayerStatsArgs, PredictionArgs, PlayerPredictionArgs
from app.agents import tools
from app.agents.provenance import begin, calls, execute
from app.agents.validation import validate_evidence
from app.repositories.synthetic import get_fixture, h2h, form, players

def run_mock(request: AnalysisRequest) -> AnalysisResponse:
    begin(); fixture=get_fixture(request.match_id); version="local"
    h2h_data=execute("get_head_to_head",tools.get_head_to_head,HeadToHeadArgs(match_id=request.match_id).model_dump(),agent_name="matchlens-investigator",agent_version=version)
    home=execute("get_team_form",tools.get_team_form,TeamFormArgs(match_id=request.match_id,team_side="home").model_dump(),agent_name="matchlens-investigator",agent_version=version)
    away=execute("get_team_form",tools.get_team_form,TeamFormArgs(match_id=request.match_id,team_side="away").model_dump(),agent_name="matchlens-investigator",agent_version=version)
    stats=execute("get_player_stats",tools.get_player_stats,PlayerStatsArgs(match_id=request.match_id).model_dump(),agent_name="matchlens-investigator",agent_version=version)
    evidence=validate_evidence(InvestigatorHandoff(evidence=[EvidenceItem(record_type="h2h",record_id=f"h2h:{request.match_id}:{i}",statement=f"Synthetic H2H meeting {i+1}: {row.home_score}-{row.away_score}.") for i,row in enumerate(h2h(request.match_id))]+[EvidenceItem(record_type="form",record_id=f"form:{fixture.home_team_id}:{i}",statement=f"Synthetic home form result: {row.score} ({row.outcome}).") for i,row in enumerate(form(fixture.home_team_id))]+[EvidenceItem(record_type="form",record_id=f"form:{fixture.away_team_id}:{i}",statement=f"Synthetic away form result: {row.score} ({row.outcome}).") for i,row in enumerate(form(fixture.away_team_id))]+[EvidenceItem(record_type="player",record_id=f"player:{row['id']}",statement=f"Synthetic player record for {row['name']}.") for row in stats["players"]]),request.match_id)
    canonical=execute("predict_match",tools.predict_match,PredictionArgs(match_id=request.match_id,minute=request.minute).model_dump(),agent_name="matchlens-predictor",agent_version=version)
    projections=[execute("predict_player",tools.predict_player,PlayerPredictionArgs(match_id=request.match_id,player_id=row["id"]).model_dump(),agent_name="matchlens-predictor",agent_version=version) for row in sorted(stats["players"],key=lambda x:(x["goals"],x["assists"],x["key_passes"]),reverse=True)[:3]]
    predictor=PredictionHandoff(forecast=canonical,player_projections=projections)
    if request.audience=="fan": summary=f"{fixture.home_team_id.title()} are favored by the synthetic model at {canonical['home_win_probability']:.1f}%, with a {canonical['draw_probability']:.1f}% draw probability."; bullets=[f"Expected goals: {canonical['expected_home_goals']:.2f}–{canonical['expected_away_goals']:.2f}.","The answer is grounded in synthetic form, player, and forecast evidence."]
    elif request.audience=="analyst": summary=f"The forecast is {canonical['home_win_probability']:.1f}% home, {canonical['draw_probability']:.1f}% draw, {canonical['away_win_probability']:.1f}% away at minute {request.minute}."; bullets=canonical["explanation"]
    else: top=projections[0]; summary=f"{top['player_name']} has the strongest available synthetic attacking signal in this fixture."; bullets=[f"Projected goals: {top['projected_goals']:.2f}; projected assists: {top['projected_assists']:.2f}.","Player projections are heuristic synthetic rates, not validated fantasy predictions."]
    tool_calls=calls(); traces=[AgentExecutionTrace(agent_name="matchlens-investigator",agent_version=version,status="success",tool_calls=[x for x in tool_calls if x.agent_name=="matchlens-investigator"]),AgentExecutionTrace(agent_name="matchlens-predictor",agent_version=version,status="success",tool_calls=[x for x in tool_calls if x.agent_name=="matchlens-predictor"]),AgentExecutionTrace(agent_name="matchlens-insight",agent_version=version,status="success")]
    return AnalysisResponse(status="ok",mode="mock",audience=request.audience,match_id=request.match_id,question=request.question,investigator=evidence,predictor=predictor,insight=InsightHandoff(summary=summary,bullets=bullets),tool_calls=tool_calls,traces=traces)
